INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしだって\nやるときはやるよ！", 102601, 0.0, "リン", 10040, 0.0, 0, 24001, "2020/04/30 12:00:00", 24, 1, 0.0, "2030/12/17 14:59:59", 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("ふぅ…\nこれであたしの仕事は\n終わりだね", 102601, 0.0, "リン", 10040, 0.0, 1, 24002, "2020/04/30 12:00:00", 24, 1, 0.0, "2030/12/17 14:59:59", 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("終わった終わった\n一人でもなんとか\nなるもんだね", 102601, 0.0, "リン", 10040, 0.0, 2, 24003, "2020/04/30 12:00:00", 24, 1, 0.0, "2030/12/17 14:59:59", 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("やったね！\nこれでようやく\nサボれるよ…", 102601, 0.0, "リン", 10040, 0.0, 3, 24004, "2020/04/30 12:00:00", 24, 2, 0.0, "2030/12/17 14:59:59", 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 102601, 0.0, "リン", 10040, 0.0, 4, 24005, "2020/04/30 12:00:00", 24, 1, 0.0, "2030/12/17 14:59:59", 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしを敵に回した\n恐ろしさ\n思い知ったか！", 102601, 0.0, "リン", 10040, 0.0, 5, 24006, "2020/04/30 12:00:00", 24, 2, 0.0, "2030/12/17 14:59:59", 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしも意外と\nやるもんでしょ？", 102601, 0.0, "リン", 10040, 0.0, 6, 24007, "2020/04/30 12:00:00", 24, 2, 0.0, "2030/12/17 14:59:59", 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("疲れた…\nねずみの逃げ足\n速すぎるよ…", 102601, 0.0, "リン", 10040, 0.0, 7, 24008, "2020/04/30 12:00:00", 24, 4, 0.0, "2030/12/17 14:59:59", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("このままじゃ\nまっひ～に\n叱られちゃうよ", 102601, 0.0, "リン", 10040, 0.0, 8, 24009, "2020/04/30 12:00:00", 24, 4, 0.0, "2030/12/17 14:59:59", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("まじめに\nやったんだけどな…\n悔しいな～", 102601, 0.0, "リン", 10040, 0.0, 9, 24010, "2020/04/30 12:00:00", 24, 4, 0.0, "2030/12/17 14:59:59", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("やられた…\nねずみって意外と\nてごわいね", 102601, 0.0, "リン", 10040, 0.0, 10, 24011, "2020/04/30 12:00:00", 24, 4, 0.0, "2030/12/17 14:59:59", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("おのれ～\nあたしのチーズを\n盗みやがって～！", 102601, 0.0, "リン", 10040, 0.0, 11, 24012, "2020/04/30 12:00:00", 24, 4, 0.0, "2030/12/17 14:59:59", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("疲れた…\nけど、次こそは\n守り抜くよ…", 102601, 0.0, "リン", 10040, 1.81, 12, 24013, "2020/04/30 12:00:00", 24, 1, 0.0, "2030/12/17 14:59:59", 4);
